import json, sqlite3

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

# Fix flights with premium_economy - remove that key from prices and available_seats
for r in conn.execute('SELECT flight_id, dates_json FROM flights WHERE source_skill=\"tau2Airline\"'):
    dates = json.loads(r['dates_json'] or '{}')
    changed = False
    for d, info in dates.items():
        for field in ('prices', 'available_seats'):
            if field in info and 'premium_economy' in info[field]:
                del info[field]['premium_economy']
                changed = True
    if changed:
        cur.execute('UPDATE flights SET dates_json=? WHERE flight_id=?', (json.dumps(dates), r['flight_id']))

# Fix passengers missing dob - add a placeholder
for r in conn.execute('SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill=\"tau2Airline\"'):
    pax = json.loads(r['passengers_json'] or '[]')
    changed = False
    for p in pax:
        if 'dob' not in p:
            p['dob'] = p.get('date_of_birth', '1990-01-01')
            changed = True
        # Remove extra fields that Pydantic doesn't expect
        for k in list(p.keys()):
            if k not in ('first_name', 'last_name', 'dob'):
                del p[k]
                changed = True
    if changed:
        cur.execute('UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?', (json.dumps(pax), r['booking_id']))

# Fix flights with None departure/arrival times
for r in conn.execute('SELECT flight_id, departure_time, arrival_time FROM flights WHERE source_skill=\"tau2Airline\"'):
    if r['departure_time'] is None or r['arrival_time'] is None:
        cur.execute('UPDATE flights SET departure_time=COALESCE(departure_time,\"00:00\"), arrival_time=COALESCE(arrival_time,\"00:00\") WHERE flight_id=?', (r['flight_id'],))

conn.commit()
conn.close()
print('DB cleaned')
"

cd /workspace && python3 -c "
import json, sqlite3

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

VALID_CABINS = {'business', 'economy', 'basic_economy'}
VALID_STATUSES = {'available', 'landed', 'cancelled', 'delayed', 'flying', 'on time'}

# Fix ALL flights - remove invalid cabin keys from prices/seats, fix statuses
for r in conn.execute('SELECT flight_id, dates_json FROM flights WHERE source_skill=\"tau2Airline\"'):
    dates = json.loads(r['dates_json'] or '{}')
    changed = False
    dates_to_remove = []
    for d, info in dates.items():
        # Fix invalid statuses
        if info.get('status') not in VALID_STATUSES:
            if info.get('status') == 'active':
                info['status'] = 'available'
                changed = True
            else:
                dates_to_remove.append(d)
                changed = True
                continue
        # Remove invalid cabin keys
        for field in ('prices', 'available_seats'):
            if field in info:
                invalid_keys = [k for k in info[field] if k not in VALID_CABINS]
                for k in invalid_keys:
                    del info[field][k]
                    changed = True
    for d in dates_to_remove:
        del dates[d]
    if changed:
        cur.execute('UPDATE flights SET dates_json=? WHERE flight_id=?', (json.dumps(dates), r['flight_id']))

conn.commit()
conn.close()
print('DB fully cleaned')
"

